package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.KeyEvent;import android.view.accessibility.AccessibilityNodeInfo;
public class StartupPolicyInstrumentation extends Instrumentation {
 private Activity activity;private int passed;private final StringBuilder results=new StringBuilder();
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private String tree(AccessibilityNodeInfo n){if(n==null)return "";StringBuilder b=new StringBuilder();if(n.getText()!=null)b.append(n.getText());b.append('\n');for(int i=0;i<n.getChildCount();i++)b.append(tree(n.getChild(i)));return b.toString();}
 private String tree(){return tree(getUiAutomation().getRootInActiveWindow());}
 private AccessibilityNodeInfo find(String text,boolean prefix,AccessibilityNodeInfo n){if(n==null)return null;String value=n.getText()==null?"":n.getText().toString();if(prefix?value.startsWith(text):value.equals(text))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=find(text,prefix,n.getChild(i));if(r!=null)return r;}return null;}
 private AccessibilityNodeInfo focused(AccessibilityNodeInfo n){if(n==null)return null;if(n.isFocused())return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=focused(n.getChild(i));if(r!=null)return r;}return null;}
 private String focus(){AccessibilityNodeInfo n=focused(getUiAutomation().getRootInActiveWindow());String t=tree(n).trim();return t.isEmpty()&&n!=null&&n.getContentDescription()!=null?n.getContentDescription().toString():t;}
 private void await(String label,java.util.concurrent.Callable<Boolean> condition)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){if(condition.call())return;SystemClock.sleep(80);}throw new IllegalStateException(label+" focus="+focus()+" UI="+tree());}
 private void text(String t)throws Exception{await(t,()->tree().contains(t));}
 private void click(String t,boolean prefix)throws Exception{await(t,()->find(t,prefix,getUiAutomation().getRootInActiveWindow())!=null);AccessibilityNodeInfo n=find(t,prefix,getUiAutomation().getRootInActiveWindow());while(!n.isClickable()){n=n.getParent();if(n==null)throw new IllegalStateException("No clickable "+t);}n.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SHOW_ON_SCREEN.getId());SystemClock.sleep(100);if(!n.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new IllegalStateException("Click "+t);waitForIdleSync();SystemClock.sleep(100);}
 private void click(String t)throws Exception{click(t,false);}
 private void focus(String t)throws Exception{await(t,()->find(t,false,getUiAutomation().getRootInActiveWindow())!=null);AccessibilityNodeInfo n=find(t,false,getUiAutomation().getRootInActiveWindow());while(!n.isFocusable()){n=n.getParent();if(n==null)throw new IllegalStateException("No focusable "+t);}if(!n.performAction(AccessibilityNodeInfo.ACTION_FOCUS))throw new IllegalStateException("Focus "+t);await("focused "+t,()->java.util.Arrays.asList(focus().split("\n")).contains(t));}
 private void key(int code){sendKeyDownUpSync(code);waitForIdleSync();SystemClock.sleep(120);}
 private void launch()throws Exception{activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));text("频道分类：");SystemClock.sleep(2300);}
 private void closeEditor()throws Exception{key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(400);if(tree().contains("保存"))key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(250);}
 private void pass(String name){passed++;results.append("PASS ").append(name).append('\n');Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}


 private void reopen(){try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -a android.intent.action.MAIN -c android.intent.category.LAUNCHER -f 0x10200000 -n com.nexttv/com.nexttv.core.tv.TvActivity")){java.io.FileInputStream input=new java.io.FileInputStream(fd.getFileDescriptor());byte[] buffer=new byte[1024];java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();int count;while((count=input.read(buffer))>=0)out.write(buffer,0,count);Bundle b=new Bundle();b.putString("stream","REOPEN "+out.toString()+" originalDestroyed="+activity.isDestroyed()+" changingConfig="+activity.isChangingConfigurations()+" finishing="+activity.isFinishing()+"\n");sendStatus(0,b);}catch(Exception e){throw new RuntimeException(e);}}
 @Override public void onStart(){try{
 activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));key(KeyEvent.KEYCODE_DPAD_LEFT);key(KeyEvent.KEYCODE_DPAD_LEFT);await("cold startup channel boundary",()->focus().equals("频道"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("Channels content header",()->focus().startsWith("频道分类："));key(KeyEvent.KEYCODE_DPAD_LEFT);if(!focus().startsWith("频道分类："))throw new IllegalStateException("Channel content crossed menu");key(KeyEvent.KEYCODE_DPAD_UP);await("Channels menu",()->focus().equals("频道"));key(KeyEvent.KEYCODE_DPAD_RIGHT);await("favorites",()->focus().equals("收藏"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("Favorites content header",()->focus().equals("刷新订阅"));key(KeyEvent.KEYCODE_DPAD_LEFT);if(!focus().equals("刷新订阅"))throw new IllegalStateException("Favorite content crossed menu");key(KeyEvent.KEYCODE_DPAD_UP);await("Favorites menu",()->focus().equals("收藏"));key(KeyEvent.KEYCODE_DPAD_RIGHT);await("settings",()->focus().equals("设置"));key(KeyEvent.KEYCODE_DPAD_RIGHT);if(!focus().equals("设置"))throw new IllegalStateException("Settings right boundary");pass("cold startup focus + navigation boundaries + menu/content Down/Up handoff hold");key(KeyEvent.KEYCODE_DPAD_DOWN);await("Settings row",()->focus().contains("节目单地址"));key(KeyEvent.KEYCODE_DPAD_LEFT);if(!focus().contains("节目单地址"))throw new IllegalStateException("Settings crossed menu");key(KeyEvent.KEYCODE_DPAD_UP);await("Settings menu",()->focus().equals("设置"));
 click("节目单地址");closeEditor();for(int i=0;i<9;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);for(int i=0;i<9;i++)key(KeyEvent.KEYCODE_DPAD_UP);SystemClock.sleep(400);await("EPG section header fully visible",()->{AccessibilityNodeInfo heading=find("节目单",false,getUiAutomation().getRootInActiveWindow());if(heading==null)return false;android.graphics.Rect bounds=new android.graphics.Rect();heading.getBoundsInScreen(bounds);return bounds.top>=64;});pass("moving focus upward restores full EPG section heading without Back");
 key(KeyEvent.KEYCODE_DPAD_DOWN);for(int i=0;i<5;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);final String priorSettingFocus=focus();getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_HOME);SystemClock.sleep(500);reopen();await("emulator warm Settings retained",()->focus().equals(priorSettingFocus)&&!tree().contains("频道分类："));pass("emulator warm return preserves Settings page and selected option");focus("频道");
 click("频道分类：",true);click("全部频道");click("CCTV1综合");text("线路 ");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_HOME);SystemClock.sleep(500);reopen();await("emulator warm player retained",()->tree().contains("线路 ")||tree().contains("频道列表"));if(tree().contains("频道分类："))throw new IllegalStateException("Emulator lost player state");pass("emulator warm return preserves live player instead of forcing Channels");
 Bundle b=new Bundle();b.putString("stream",results+"Startup policy: "+passed+" groups passed\n");finish(Activity.RESULT_OK,b);
 }catch(Throwable t){Bundle b=new Bundle();b.putString("stream",t.toString());finish(Activity.RESULT_CANCELED,b);}}
}
